/* ══════════════════════════════════════════════════════════
   HELPERS
══════════════════════════════════════════════════════════ */
const fmt   = n => '₡' + n.toLocaleString('es-CR');
const waUrl = msg => `https://wa.me/${FM.whatsapp}?text=${encodeURIComponent(msg)}`;

function alaCarte(comp){
  return Object.entries(comp).reduce((s,[k,v])=>s+v*FM.unit[k],0);
}
function savingsOf(plan){
  const ac = alaCarte(plan.comp);
  return { ac, saved: ac-plan.price, pct: Math.round((ac-plan.price)/ac*100) };
}

