/* PAGE DETECTION */
const PAGE = (function(){
  const p = location.pathname;
  if(p.includes('comercio')) return 'comercio';
  if(p.includes('eventos'))  return 'eventos';
  return 'index';
})();
let currentSection = PAGE;
let selectedPlan       = null;
let builderVals        = { foto:0, story:0, reelOrg:2, reelPro:1, visita:1 };
let selectedEvento     = null;
let ivaEnabled         = false;   // { id, track, price, name, sub }
let currentEventType   = 'pequeno';
let selectedTrack      = null;
let selectedAddons     = new Set();
let ccHoursVal         = 3;
let currentComercioTab = 'video';

/* ══════════════════════════════════════════════════════════
   SECCIÓN / NAV
══════════════════════════════════════════════════════════ */
function showSection(name){
  // multi-page: navigation handled by <a href> links
  currentSection = name;
  updateFooter();
}

/* ══════════════════════════════════════════════════════════
   TABS COMERCIO
══════════════════════════════════════════════════════════ */
function switchTab(name, btn){
  document.querySelectorAll('#comercio-tabs .tab-btn').forEach(b=>b.classList.remove('active'));
  document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));
  document.getElementById('tp-'+name).classList.add('active');
  btn.classList.add('active');
  currentComercioTab = name;
  if(name !== 'builder'){ selectedPlan = null; }
  updateFooter();
}

/* ══════════════════════════════════════════════════════════
   TABS EVENTOS (por tipo)
══════════════════════════════════════════════════════════ */
function switchEventoType(eventId, btn){
  document.querySelectorAll('#ev-tabs .tab-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  currentEventType = eventId;
  selectedTrack    = null;
  selectedEvento   = null;
  selectedAddons.clear();
  document.getElementById('cc-wrap').classList.remove('show');
  renderEventoTracks();
  renderAddons();
  updateEvTotal();
}

/* ══════════════════════════════════════════════════════════
   RENDER PLAN CARDS
══════════════════════════════════════════════════════════ */
function renderPlans(plans, gridId, tabType){
  const grid = document.getElementById(gridId);
  grid.innerHTML = plans.map(p=>{
    const {ac,saved,pct} = savingsOf(p);
    const feats = Object.entries(p.comp)
      .map(([k,v])=>`<li>${v} ${FM.labels[k]}</li>`).join('');
    return `
    <div class="plan-card${p.featured?' featured':''}">
      ${p.badge?`<div class="plan-badge">${p.badge}</div>`:''}
      <div class="savings-strip">
        <span class="alacarte">À la carte ${fmt(ac)}</span>
        <span class="saving">Ahorrás ${pct}%</span>
      </div>
      <div class="plan-name">${p.name}</div>
      <div class="plan-price">${fmt(p.price)}<small>/mes</small></div>
      <div class="plan-divider"></div>
      <ul class="plan-feats">${feats}</ul>
      <li class="plan-feats" style="list-style:none;margin-top:4px">
        <span style="font-size:12px;color:var(--dim)">✓ Transporte incluido</span>
      </li>
      <button class="plan-cta" onclick="selectPlan(${JSON.stringify(p).replace(/"/g,'&quot;')}, '${tabType}')">
        Cotizar este plan
      </button>
    </div>`;
  }).join('');
}

function selectPlan(plan, tabType){
  selectedPlan = { name:plan.name, price:plan.price, type:tabType,
    detail:`Plan *${plan.name}* (${tabType==='video'?'Solo Video':'Video+Foto'}) — ${fmt(plan.price)}/mes` };
  updateFooter();
  document.getElementById('sf-amount').classList.add('pulse');
  setTimeout(()=>document.getElementById('sf-amount').classList.remove('pulse'),600);
}

/* ══════════════════════════════════════════════════════════
   RENDER BUILDER
══════════════════════════════════════════════════════════ */
const BUILDER_CONFIG = [
  { key:'foto',    label:'Fotografías editadas',  unit:'₡4,000 c/u',  libre:true  },
  { key:'story',   label:'Stories orgánicas',     unit:'₡8,000 c/u',  libre:true  },
  { key:'reelOrg', label:'Reels orgánicos',       unit:'₡18,000 c/u', libre:false, min:2, max:12 },
  { key:'reelPro', label:'Reels profesionales',   unit:'₡35,000 c/u', libre:false, min:1, max:10 },
  { key:'visita',  label:'Visitas al local',      unit:'₡10,000 c/u', libre:false, min:1, max:3  },
];

function renderBuilder(){
  const wrap = document.getElementById('builder-sliders');
  wrap.innerHTML = BUILDER_CONFIG.map(item=>{
    const v = builderVals[item.key];
    if(item.libre){
      return `
      <div class="sl-card">
        <div class="sl-top">
          <div class="sl-info"><div class="sl-name">${item.label}</div><div class="sl-unit">${item.unit}</div></div>
          <div class="sl-count" id="bc-${item.key}">${v}</div>
        </div>
        <div class="stepper">
          <button class="stp-btn" onclick="stepBuilder('${item.key}',-1)">−</button>
          <input type="number" class="stp-input" id="bv-${item.key}" value="${v}" min="0"
                 oninput="inputBuilder('${item.key}',this.value)">
          <button class="stp-btn" onclick="stepBuilder('${item.key}',1)">+</button>
        </div>
      </div>`;
    } else {
      return `
      <div class="sl-card">
        <div class="sl-top">
          <div class="sl-info"><div class="sl-name">${item.label}</div><div class="sl-unit">${item.unit} · mín ${item.min} máx ${item.max}</div></div>
          <div class="sl-count" id="bc-${item.key}">${v}</div>
        </div>
        <input type="range" min="${item.min}" max="${item.max}" value="${v}"
               oninput="slideBuilder('${item.key}',this.value)">
      </div>`;
    }
  }).join('');
}

function stepBuilder(key, delta){
  let v = builderVals[key]+delta;
  if(v<0) v=0;
  builderVals[key]=v;
  const inp = document.getElementById('bv-'+key);
  const cnt = document.getElementById('bc-'+key);
  if(inp) inp.value=v;
  if(cnt) cnt.textContent=v;
  updateBuilderTotal();
}

function inputBuilder(key, val){
  let v = parseInt(val)||0;
  if(v<0) v=0;
  builderVals[key]=v;
  const cnt = document.getElementById('bc-'+key);
  if(cnt) cnt.textContent=v;
  updateBuilderTotal();
}

function slideBuilder(key, val){
  builderVals[key]=parseInt(val);
  const cnt = document.getElementById('bc-'+key);
  if(cnt) cnt.textContent=val;
  updateBuilderTotal();
}

function updateBuilderTotal(){
  const total = BUILDER_CONFIG.reduce((s,c)=>s+builderVals[c.key]*FM.unit[c.key],0);
  selectedPlan = (total>0 && currentComercioTab==='builder') ? { name:'A medida', price:total, type:'builder' } : null;
  const tip = document.getElementById('tip-box');
  const lowestV = FM.planesVideo[0].price;
  if(total===0){ tip.classList.remove('show'); return; }
  if(total>=lowestV){
    tip.innerHTML=`💡 Tu selección supera el plan <strong>Básico Video (${fmt(lowestV)}/mes)</strong>. Considerá un plan para obtener más contenido al mismo precio.`;
    tip.classList.add('show');
  } else { tip.classList.remove('show'); }
  updateFooter();
}

