/* ══════════════════════════════════════════════════════════
   RENDER EVENTOS — track cards dentro del tipo seleccionado
══════════════════════════════════════════════════════════ */
const TRACK_LABELS = { foto:'Solo Fotografía', video:'Solo Video', completa:'Cobertura Completa' };
const TRACK_ICONS  = { foto:'📸', video:'🎬', completa:'✨' };

function renderEventoTracks(){
  const ev = FM.eventos.find(e=>e.id===currentEventType);
  if(!ev) return;
  document.getElementById('ev-subtitle').textContent = ev.sub;
  document.getElementById('ev-tracks').innerHTML = Object.entries(ev.tracks).map(([track,data])=>{
    const isSel = selectedTrack === track;
    let savingsBadge = '';
    if(track === 'completa' && ev.tracks.foto && ev.tracks.video){
      const separated = ev.tracks.foto.price + ev.tracks.video.price;
      const saved = separated - data.price;
      if(saved > 0){
        savingsBadge = `<div class="etc-savings">Ahorrás ${fmt(saved)} vs. comprar por separado</div>`;
      }
    }
    return `
    <div class="ev-track-card${isSel?' sel':''}" onclick="selectTrack('${track}')">
      <div class="ev-check"></div>
      <div class="etc-icon">${TRACK_ICONS[track]}</div>
      <div class="etc-name">${TRACK_LABELS[track]}</div>
      <div class="etc-price">${fmt(data.price)}</div>
      <div class="etc-meta">${data.meta}</div>
      ${savingsBadge}
    </div>`;
  }).join('');
}

function selectTrack(track){
  if(selectedTrack===track){ selectedTrack=null; selectedEvento=null; }
  else {
    const ev = FM.eventos.find(e=>e.id===currentEventType);
    if(!ev) return;
    selectedTrack  = track;
    selectedEvento = { id:currentEventType, track, price:ev.tracks[track].price, name:ev.name, sub:ev.sub };
  }
  // Si el track activo no admite sdhl, deseleccionarlo
  if(selectedTrack==='foto' || !selectedTrack){
    selectedAddons.delete('sdhl');
    document.getElementById('cc-wrap').classList.toggle('show', selectedAddons.has('cc'));
  }
  renderEventoTracks();
  renderAddons();
  updateEvTotal();
}

/* ══════════════════════════════════════════════════════════
   RENDER ADD-ONS
══════════════════════════════════════════════════════════ */
function renderAddons(){
  const visible = FM.addons.filter(a=>{
    if(!a.tracks) return true;
    if(!selectedTrack) return true;
    return a.tracks.includes(selectedTrack);
  });
  document.getElementById('addons-grid').innerHTML = visible.map(a=>`
    <div class="ao-card${selectedAddons.has(a.id)?' sel':''}" id="ao-${a.id}" onclick="toggleAddon('${a.id}')">
      <div class="ao-check"></div>
      <div class="ao-body">
        <div class="ao-name">${a.name}</div>
        <div class="ao-desc">${a.desc}</div>
        <div class="ao-price">
          ${a.type==='flat'?fmt(a.price):`${fmt(a.price)}<small>/hora</small>`}
        </div>
      </div>
    </div>`).join('');
}

function toggleAddon(id){
  const card = document.getElementById('ao-'+id);
  if(selectedAddons.has(id)){
    selectedAddons.delete(id);
    card.classList.remove('sel');
  } else {
    selectedAddons.add(id);
    card.classList.add('sel');
  }
  const ccWrap = document.getElementById('cc-wrap');
  ccWrap.classList.toggle('show', selectedAddons.has('cc'));
  updateEvTotal();
}

/* ══════════════════════════════════════════════════════════
   CONTENT CREATOR HORAS
══════════════════════════════════════════════════════════ */
function ccHours(delta){
  ccHoursVal = Math.max(3, ccHoursVal+delta);
  document.getElementById('cc-h-val').textContent   = ccHoursVal;
  document.getElementById('cc-h-total').textContent = fmt(ccHoursVal*15000);
  updateEvTotal();
}

/* ══════════════════════════════════════════════════════════
   TOTAL EVENTOS
══════════════════════════════════════════════════════════ */
function updateEvTotal(){
  let total = 0;
  let lines = [];

  if(selectedEvento){
    total += selectedEvento.price;
    const trackLabel = { foto:'Solo Fotografía', video:'Solo Video', completa:'Cobertura Completa' }[selectedEvento.track];
    lines.push(`*${selectedEvento.name} — ${selectedEvento.sub}*\n${trackLabel} — ${fmt(selectedEvento.price)}`);
  }

  selectedAddons.forEach(id=>{
    const a = FM.addons.find(x=>x.id===id);
    if(!a) return;
    if(a.type==='flat'){ total+=a.price; lines.push(`${a.name} — ${fmt(a.price)}`); }
    else if(a.id==='cc'){ const cc=ccHoursVal*a.price; total+=cc; lines.push(`Content Creator (${ccHoursVal}h) — ${fmt(cc)}`); }
  });

  const sfAmount = document.getElementById('sf-amount');
  const sfSub    = document.getElementById('sf-sub');
  const waBtn    = document.getElementById('wa-btn');

  const imgBtn2 = document.getElementById('img-btn');
  if(total===0){ sfAmount.textContent='—'; sfSub.textContent=''; waBtn.href=`https://wa.me/${FM.whatsapp}`; imgBtn2.classList.remove('show'); return; }

  sfAmount.textContent = fmt(total);
  sfSub.textContent    = '';
  imgBtn2.classList.add('show');
  const msg = `Hola, me interesa una cobertura de Focus Media.\n\n${lines.join('\n\n')}\n\n*Total: ${fmt(total)}*\n\n¿Podemos coordinar?`;
  waBtn.href = waUrl(msg);
}

/* ══════════════════════════════════════════════════════════
   FOOTER STICKY GLOBAL
══════════════════════════════════════════════════════════ */
function toggleIva(){
  ivaEnabled = document.getElementById('iva-check').checked;
  updateFooter();
}

function updateFooter(){
  const sfAmount = document.getElementById('sf-amount');
  const sfSub    = document.getElementById('sf-sub');
  const waBtn    = document.getElementById('wa-btn');
  const imgBtn   = document.getElementById('img-btn');
  const ivaWrap  = document.getElementById('iva-wrap');

  // Reset toggles
  ivaWrap.classList.remove('show');
  imgBtn.classList.remove('show');

  if(currentSection==='index'){
    sfAmount.textContent='—'; sfSub.textContent='';
    waBtn.href=`https://wa.me/${FM.whatsapp}?text=${encodeURIComponent('Hola, me interesa una propuesta de Focus Media.')}`;
    return;
  }
  if(currentSection==='eventos'){ updateEvTotal(); return; }

  // Comercio — mostrar toggle IVA siempre
  ivaWrap.classList.add('show');
  if(!selectedPlan){ sfAmount.textContent='—'; sfSub.textContent=''; waBtn.href=`https://wa.me/${FM.whatsapp}`; return; }

  imgBtn.classList.add('show');
  const base  = selectedPlan.price;
  const iva   = ivaEnabled ? Math.round(base * 0.13) : 0;
  const total = base + iva;

  sfAmount.innerHTML = `${fmt(total)}<span style="font-size:13px;font-weight:300;color:var(--muted);margin-left:3px">/mes</span>`;

  if(selectedPlan.type==='builder'){
    sfSub.textContent = ivaEnabled ? `base ${fmt(base)} + IVA ${fmt(iva)}` : 'sin IVA';
    const items = BUILDER_CONFIG
      .filter(c=>builderVals[c.key]>0)
      .map(c=>`  • ${c.label}: ${builderVals[c.key]} (${fmt(builderVals[c.key]*FM.unit[c.key])})`);
    const ivaNote = ivaEnabled ? `\n_Incluye IVA ${fmt(iva)}_` : ' _(sin IVA)_';
    const msg = `Hola, armé un plan a medida en Focus Media:\n${items.join('\n')}\n\n*Total: ${fmt(total)}/mes*${ivaNote}\n\n¿Podemos conversar?`;
    waBtn.href = waUrl(msg);
  } else {
    sfSub.textContent = ivaEnabled ? `base ${fmt(base)} + IVA ${fmt(iva)}` : 'sin IVA';
    const plan = (selectedPlan.type==='video'?FM.planesVideo:FM.planesFoto).find(p=>p.name===selectedPlan.name);
    const feats = plan ? Object.entries(plan.comp).map(([k,v])=>`  • ${v} ${FM.labels[k]}`).join('\n') : '';
    const ivaNote = ivaEnabled ? `\n_Incluye IVA ${fmt(iva)}_` : ' _(sin IVA)_';
    const msg = `Hola, me interesa el plan *${selectedPlan.name}* ${selectedPlan.type==='video'?'(Solo Video)':'(Video+Foto)'} de Focus Media.\n\n${feats}\n\n*Total: ${fmt(total)}/mes*${ivaNote}\n\n¿Podemos conversar?`;
    waBtn.href = waUrl(msg);
  }
}

/* ══════════════════════════════════════════════════════════
   GENERAR IMAGEN (Canvas 1080×1920 stories)
══════════════════════════════════════════════════════════ */
function generateQuoteImage(){
  const W = 1080, H = 1920;
  const canvas = document.createElement('canvas');
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext('2d');

  /* ── fondo ── */
  ctx.fillStyle = '#080808';
  ctx.fillRect(0, 0, W, H);

  /* ── gradiente dorado radial centrado-superior ── */
  const grd = ctx.createRadialGradient(W/2, 0, 0, W/2, 0, H*0.75);
  grd.addColorStop(0,   'rgba(201,161,99,0.13)');
  grd.addColorStop(0.5, 'rgba(201,161,99,0.04)');
  grd.addColorStop(1,   'rgba(0,0,0,0)');
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, W, H);

  /* ── helpers ── */
  const ACCENT  = '#C9A163';
  const WHITE   = '#FFFFFF';
  const DIM     = 'rgba(255,255,255,0.45)';
  const DIVIDER = 'rgba(201,161,99,0.3)';

  function hline(y){ ctx.fillStyle=DIVIDER; ctx.fillRect(120, y, W-240, 1); }

  /* ── recopilar datos según sección ── */
  let planName='', planSub='', priceBase=0, priceTotal=0, ivaAmt=0, priceLabel='', addonLines=[];

  if(currentSection==='comercio' && selectedPlan){
    planName  = selectedPlan.name;
    planSub   = selectedPlan.type==='video' ? 'Solo Video' : selectedPlan.type==='builder' ? 'Plan a medida' : 'Video + Foto';
    priceBase = selectedPlan.price;
    ivaAmt    = ivaEnabled ? Math.round(priceBase*0.13) : 0;
    priceTotal= priceBase + ivaAmt;
    priceLabel= '/mes';
  } else if(currentSection==='eventos' && selectedEvento){
    planName   = selectedEvento.name;
    const tMap = {foto:'Solo Fotografía', video:'Solo Video', completa:'Cobertura Completa'};
    planSub    = selectedEvento.sub + ' · ' + (tMap[selectedEvento.track]||'');
    priceTotal = selectedEvento.price;
    priceLabel = '';
    selectedAddons.forEach(id=>{
      const a = FM.addons.find(x=>x.id===id);
      if(!a) return;
      if(a.type==='flat'){ priceTotal+=a.price; addonLines.push(a.name+'  '+fmt(a.price)); }
      else if(a.id==='cc'){ const cc=ccHoursVal*a.price; priceTotal+=cc; addonLines.push('Content Creator ('+ccHoursVal+'h)  '+fmt(cc)); }
    });
  } else { return; }

  /* ══ dibujo ══ */
  let y = 200;

  /* ── logo ── */
  const logoImg = document.querySelector('.nav-brand img');
  if(logoImg && logoImg.complete && logoImg.naturalWidth){
    const lSize = 110;
    ctx.drawImage(logoImg, W/2 - lSize/2, y, lSize, lSize);
    y += lSize + 28;
  } else { y += 50; }

  /* ── "FOCUS MEDIA" ── */
  ctx.fillStyle = WHITE;
  ctx.font = '500 34px "DM Sans", sans-serif';
  ctx.textAlign = 'center';
  ctx.letterSpacing = '6px';
  ctx.fillText('FOCUS MEDIA', W/2, y);
  ctx.letterSpacing = '0px';
  y += 36;

  /* ── "Costa Rica" muted ── */
  ctx.fillStyle = DIM;
  ctx.font = '300 24px "DM Sans", sans-serif';
  ctx.fillText('Costa Rica', W/2, y);
  y += 90;

  hline(y); y += 70;

  /* ── etiqueta propuesta ── */
  ctx.fillStyle = ACCENT;
  ctx.font = '500 22px "DM Sans", sans-serif';
  ctx.letterSpacing = '5px';
  ctx.fillText('P R O P U E S T A', W/2, y);
  ctx.letterSpacing = '0px';
  y += 110;

  /* ── nombre del plan (wrap si largo) ── */
  ctx.fillStyle = WHITE;
  ctx.font = '400 96px "Cormorant Garamond", serif';
  ctx.textAlign = 'center';
  const words = planName.split(' ');
  let ln1='', ln2='';
  words.forEach(function(w){
    const test = ln1 ? ln1+' '+w : w;
    if(ctx.measureText(test).width > W-240 && ln1){ ln2=(ln2?ln2+' ':'')+w; }
    else { ln1=test; }
  });
  if(ln2){ ctx.fillText(ln1, W/2, y); y+=110; ctx.fillText(ln2, W/2, y); y+=60; }
  else { ctx.fillText(planName, W/2, y); y+=60; }

  /* ── subtipo ── */
  ctx.fillStyle = DIM;
  ctx.font = '300 30px "DM Sans", sans-serif';
  ctx.fillText(planSub, W/2, y);
  y += 90;

  hline(y); y += 100;

  /* ── precio (inline con /mes) ── */
  ctx.textAlign = 'left';
  ctx.fillStyle = ACCENT;
  ctx.font = '300 108px "Cormorant Garamond", serif';
  const priceW = ctx.measureText(fmt(priceTotal)).width;

  if(priceLabel){
    ctx.font = '300 34px "DM Sans", sans-serif';
    const labelW = ctx.measureText(priceLabel).width;
    const gap = 12;
    const blockW = priceW + gap + labelW;
    const startX = W/2 - blockW/2;

    // Big price
    ctx.fillStyle = ACCENT;
    ctx.font = '300 108px "Cormorant Garamond", serif';
    ctx.fillText(fmt(priceTotal), startX, y);

    // /mes — baseline aligned to bottom-third of price (y - 24 feels like bottom-right subscript)
    ctx.fillStyle = DIM;
    ctx.font = '300 34px "DM Sans", sans-serif';
    ctx.fillText(priceLabel, startX + priceW + gap, y - 24);
    y += 28;
  } else {
    ctx.fillStyle = ACCENT;
    ctx.font = '300 108px "Cormorant Garamond", serif';
    ctx.fillText(fmt(priceTotal), W/2 - priceW/2, y);
    y += 28;
  }
  ctx.textAlign = 'center';

  /* ── desglose IVA ── */
  if(ivaEnabled && ivaAmt>0 && currentSection==='comercio'){
    y += 16;
    ctx.fillStyle = 'rgba(201,161,99,0.55)';
    ctx.font = '300 24px "DM Sans", sans-serif';
    ctx.fillText('Base '+fmt(priceBase)+'  +  IVA '+fmt(ivaAmt), W/2, y);
    y += 30;
  }

  /* ── addons evento ── */
  if(addonLines.length){
    y += 30;
    ctx.fillStyle = DIM;
    ctx.font = '300 24px "DM Sans", sans-serif';
    addonLines.forEach(function(al){ ctx.fillText(al, W/2, y); y+=38; });
  }

  /* ── servicios incluidos ── */
  var featLines = [];

  if(currentSection==='comercio' && selectedPlan){
    if(selectedPlan.type !== 'builder'){
      var planData = (selectedPlan.type==='video' ? FM.planesVideo : FM.planesFoto).find(function(p){ return p.name===selectedPlan.name; });
      if(planData){
        Object.entries(planData.comp).forEach(function([k,v]){
          featLines.push(v + ' ' + (FM.labels[k]||k));
        });
      }
    } else {
      BUILDER_CONFIG.filter(function(c){ return builderVals[c.key]>0; }).forEach(function(c){
        featLines.push(builderVals[c.key] + ' ' + c.label);
      });
    }
  }

  if(currentSection==='eventos' && selectedEvento){
    var evData = FM.eventos.find(function(e){ return e.id===selectedEvento.id; });
    if(evData && evData.tracks[selectedEvento.track]){
      var meta = evData.tracks[selectedEvento.track].meta;
      meta.split(' · ').forEach(function(s){ if(s.trim()) featLines.push(s.trim()); });
    }
    selectedAddons.forEach(function(id){
      var a = FM.addons.find(function(x){ return x.id===id; });
      if(!a) return;
      if(a.id==='cc') featLines.push('Content Creator (' + ccHoursVal + 'h)');
      else featLines.push(a.name);
    });
  }

  if(featLines.length){
    y += 50;
    hline(y); y += 60;
    ctx.fillStyle = ACCENT;
    ctx.font = '500 20px "DM Sans", sans-serif';
    ctx.letterSpacing = '4px';
    ctx.fillText('I N C L U Y E', W/2, y);
    ctx.letterSpacing = '0px';
    y += 52;
    featLines.forEach(function(fl){
      ctx.fillStyle = 'rgba(255,255,255,0.82)';
      ctx.font = '300 30px "DM Sans", sans-serif';
      ctx.fillText(fl, W/2, y);
      y += 48;
    });
  }

  /* ── footer ── */
  const footerY = H - 160;
  hline(footerY);

  ctx.fillStyle = WHITE;
  ctx.font = '500 26px "DM Sans", sans-serif';
  ctx.letterSpacing = '4px';
  ctx.fillText('FOCUS MEDIA', W/2, footerY + 55);
  ctx.letterSpacing = '0px';

  ctx.fillStyle = DIM;
  ctx.font = '300 22px "DM Sans", sans-serif';
  ctx.fillText('focusmedia.framer.website', W/2, footerY + 92);

  /* ── descargar ── */
  canvas.toBlob(function(blob){
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const slug = planName.toLowerCase().replace(/\s+/g,'-').replace(/[^a-z0-9-]/g,'');
    a.download = 'focus-media-propuesta-'+slug+'.png';
    a.click();
    setTimeout(function(){ URL.revokeObjectURL(url); }, 5000);
  }, 'image/png');
}

/* ══════════════════════════════════════════════════════════
   INIT
══════════════════════════════════════════════════════════ */
(function init(){
  // ── inject logo into nav and hero ──
  const _navLogo = document.getElementById('nav-logo-img');
  if(_navLogo) _navLogo.src = LOGO_B64;
  const _heroLogo = document.getElementById('hero-logo-img');
  if(_heroLogo) _heroLogo.src = LOGO_B64;

  // ── mark active nav link ──
  const _activeLink = document.getElementById('nav-' + PAGE);
  if(_activeLink) _activeLink.classList.add('active');

  // ── page-specific init ──
  if(PAGE === 'comercio'){
    const nota = '† El cliente elige entre <strong>Reel cinematográfico</strong> (narrativo/mood) o <strong>Reel dinámico con subtítulos</strong> (ritmo rápido, texto en pantalla). Precios mensuales. Transporte incluido dentro del GAM.';
    renderPlans(FM.planesVideo, 'grid-video', 'video');
    document.getElementById('nota-video').innerHTML = nota;
    renderPlans(FM.planesFoto, 'grid-foto', 'foto');
    document.getElementById('nota-foto').innerHTML = nota;
    renderBuilder();
    renderTypes();
  }

  if(PAGE === 'eventos'){
    renderEventoTracks();
    renderAddons();
    renderGear();
    renderEventoTypes();
  }

  updateFooter();
})();